create table if not exists public.command_mission_types (mission_type_key text primary key,display_name text not null,methodology jsonb not null default '{}'::jsonb,methodology_version text not null default '1.0',default_command_definition_id uuid null references public.command_definitions(id),registry_destination text null,verification_standard jsonb not null default '{}'::jsonb,duplicate_control_profile jsonb not null default '{}'::jsonb,research_resiliency jsonb not null default '{}'::jsonb,reporting_template text null,quality_control_requirements jsonb not null default '{}'::jsonb,state_context_required boolean not null default true,agent_selection_behavior jsonb not null default '{}'::jsonb,enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
insert into public.command_mission_types (mission_type_key,display_name,methodology,methodology_version,default_command_definition_id,registry_destination,verification_standard,duplicate_control_profile,research_resiliency,reporting_template,quality_control_requirements,state_context_required,agent_selection_behavior) values
('PUBLISHER_DISCOVERY','Publisher Discovery',jsonb_build_object('purpose','Identify and verify official procurement publishers for a state','candidate_staging_required',true,'human_registry_admission_required',true),'1.0',(select id from public.command_definitions where command_key='AADP_STATE_PUBLISHER_DISCOVERY' and enabled=true order by created_at desc limit 1),'publisher_registry',jsonb_build_object('official_source_required',true),jsonb_build_object('registry_duplicate_check_required',true),jsonb_build_object('source_fallback_required',true),'publisher_discovery_report',jsonb_build_object('evidence_required',true),true,jsonb_build_object('mode','operator_selected')),
('ACQUISITION_DISCOVERY','Acquisition Discovery',jsonb_build_object('purpose','Acquire, normalize, qualify, analyze, and report procurement opportunities while preserving AADP progression'),'1.0',(select id from public.command_definitions where command_key='AADP_PUBLISHER_ACQUISITION' and enabled=true order by created_at desc limit 1),'state_contract_opportunities',jsonb_build_object('reconciliation_required',true,'semantic_completion_required',true),jsonb_build_object('source_record_deduplication_required',true),jsonb_build_object('durable_dispatch_required',true),'acquisition_discovery_report',jsonb_build_object('aadp_non_regression_required',true),true,jsonb_build_object('mode','operator_selected')),
('BUSINESS_DEVELOPMENT_DISCOVERY','Business Development Discovery',jsonb_build_object('qualification_question','CAN APROPOS LEGITIMATELY ENTER THIS ORGANIZATION''S BUSINESS-DEVELOPMENT ECOSYSTEM AND RECEIVE MEANINGFUL ADVISORY SUPPORT?','directory_listing_sufficient',false,'verified_advisory_pathway_required',true),'1.0',null,'business_development_registry',jsonb_build_object('functioning_access_mechanism_required',true),jsonb_build_object('organization_duplicate_check_required',true),jsonb_build_object('alternate_access_path_verification',true),'business_development_discovery_report',jsonb_build_object('generic_economic_development_page_insufficient',true),true,jsonb_build_object('mode','operator_selected')),
('OPPORTUNITY_PARTNER_DISCOVERY','Opportunity Partner Discovery',jsonb_build_object('purpose','Identify verified organizations capable of expanding procurement opportunity access through existing programs and networks'),'1.0',null,'opportunity_partner_registry',jsonb_build_object('official_source_required',true),jsonb_build_object('organization_duplicate_check_required',true),jsonb_build_object('source_fallback_required',true),'opportunity_partner_discovery_report',jsonb_build_object('evidence_required',true),true,jsonb_build_object('mode','operator_selected')),
('INSTITUTIONAL_BUYER_DISCOVERY','Institutional Buyer Discovery',jsonb_build_object('purpose','Identify verified institutional prospects capable of buying, sponsoring, piloting, licensing, distributing, or funding APROPOS systems'),'1.0',null,'institutional_buyer_registry',jsonb_build_object('buyer_qualification_required',true),jsonb_build_object('organization_duplicate_check_required',true),jsonb_build_object('source_fallback_required',true),'institutional_buyer_discovery_report',jsonb_build_object('commercial_fit_evidence_required',true),true,jsonb_build_object('mode','operator_selected')),
('STATE_MISSION','State Mission',jsonb_build_object('purpose','Coordinate state-level onboarding and operational readiness without auto-authorizing child missions'),'1.0',null,'state_inventory',jsonb_build_object('capability_evidence_required',true),jsonb_build_object(),jsonb_build_object(),'state_mission_report',jsonb_build_object('operator_authorization_required',true),true,jsonb_build_object('mode','operator_selected')) on conflict (mission_type_key) do nothing;

alter table public.command_runs add column if not exists mission_type_key text null references public.command_mission_types(mission_type_key),add column if not exists mission_name text null,add column if not exists state_code text null,add column if not exists assigned_agent text null,add column if not exists parent_run_id uuid null references public.command_runs(id) on delete set null,add column if not exists last_activity_at timestamptz null,add column if not exists progress_mode text null,add column if not exists progress_value numeric(5,2) null,add column if not exists result_summary text null,add column if not exists warning_count integer not null default 0,add column if not exists failure_count integer not null default 0,add column if not exists action_required boolean not null default false,add column if not exists registry_impact jsonb not null default '{}'::jsonb,add column if not exists report_reference text null;
alter table public.command_runs add constraint command_runs_state_code_gate_a_check check (state_code is null or state_code ~ '^[A-Z]{2}$'),add constraint command_runs_progress_mode_gate_a_check check (progress_mode is null or progress_mode in ('TASK','STAGE','INDETERMINATE')),add constraint command_runs_progress_value_gate_a_check check (progress_value is null or (progress_value >= 0 and progress_value <= 100));
create index if not exists command_runs_mission_type_idx on public.command_runs(mission_type_key,created_at desc); create index if not exists command_runs_state_mission_idx on public.command_runs(state_code,created_at desc) where state_code is not null; create index if not exists command_runs_parent_idx on public.command_runs(parent_run_id) where parent_run_id is not null;

create table public.command_stage_projection (id uuid primary key default gen_random_uuid(),command_run_id uuid not null references public.command_runs(id) on delete cascade,stage_key text not null,display_name text not null,display_state text not null default 'NOT STARTED',sequence_number integer not null default 0,progress_value numeric(5,2),started_at timestamptz,completed_at timestamptz,records_processed integer not null default 0,warning_count integer not null default 0,failure_count integer not null default 0,retry_count integer not null default 0,source_projection text,evidence jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now(),unique(command_run_id,stage_key),check(display_state in ('NOT STARTED','QUEUED','INITIALIZING','IN PROGRESS','COMPLETED','COMPLETED WITH WARNINGS','PARTIAL COMPLETE','ACTION REQUIRED','PAUSED','CANCELLED','FAILED')),check(progress_value is null or progress_value between 0 and 100)); create index command_stage_projection_run_sequence_idx on public.command_stage_projection(command_run_id,sequence_number);
create table public.state_inventory (state_code text primary key,state_name text not null,inventory_status text not null default 'UNEVALUATED',overall_readiness text not null default 'UNEVALUATED',current_mission_id uuid references public.command_runs(id) on delete set null,last_mission_id uuid references public.command_runs(id) on delete set null,next_scheduled_mission_at timestamptz,current_exceptions jsonb not null default '[]'::jsonb,next_recommended_mission_type text references public.command_mission_types(mission_type_key),onboarding_started_at timestamptz,operational_at timestamptz,last_evaluated_at timestamptz,evidence jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(state_code ~ '^[A-Z]{2}$'),check(inventory_status in ('UNEVALUATED','ONBOARDING','OPERATIONAL','MISSION_RUNNING','ACTION_REQUIRED','PAUSED')),check(overall_readiness in ('UNEVALUATED','NOT_READY','PARTIALLY_READY','READY','ACTION_REQUIRED')));
insert into public.state_inventory(state_code,state_name) values ('NV','Nevada'),('CA','California'),('AZ','Arizona') on conflict do nothing;
create table public.state_capability_status (state_code text not null references public.state_inventory(state_code) on delete cascade,capability_key text not null,mission_type_key text references public.command_mission_types(mission_type_key),mission_completion_status text not null default 'NOT_EVALUATED',readiness_status text not null default 'UNEVALUATED',evidence_sufficient boolean not null default false,evidence jsonb not null default '{}'::jsonb,last_mission_id uuid references public.command_runs(id) on delete set null,last_evaluated_at timestamptz,updated_at timestamptz not null default now(),primary key(state_code,capability_key),check(mission_completion_status in ('NOT_EVALUATED','NOT_STARTED','RUNNING','COMPLETED','COMPLETED_WITH_WARNINGS','PARTIAL_COMPLETE','ACTION_REQUIRED','FAILED')),check(readiness_status in ('UNEVALUATED','NOT_READY','READY','ACTION_REQUIRED')));
insert into public.state_capability_status(state_code,capability_key,mission_type_key) select s.state_code,c.capability_key,c.mission_type_key from public.state_inventory s cross join (values ('PUBLISHER_DISCOVERY','PUBLISHER_DISCOVERY'),('ACQUISITION','ACQUISITION_DISCOVERY'),('BUSINESS_DEVELOPMENT_DISCOVERY','BUSINESS_DEVELOPMENT_DISCOVERY'),('OPPORTUNITY_PARTNER_DISCOVERY','OPPORTUNITY_PARTNER_DISCOVERY'),('INSTITUTIONAL_BUYER_DISCOVERY','INSTITUTIONAL_BUYER_DISCOVERY'),('STATE_OPERATIONAL_READINESS','STATE_MISSION')) c(capability_key,mission_type_key) where s.state_code in ('NV','CA','AZ') on conflict do nothing;
create table public.state_capability_dependencies (capability_key text not null,depends_on_capability_key text not null,dependency_type text not null default 'PREREQUISITE',required boolean not null default true,rationale text,enabled boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),primary key(capability_key,depends_on_capability_key),check(capability_key<>depends_on_capability_key),check(dependency_type in ('PREREQUISITE','READINESS_EVIDENCE','OPTIONAL')));
insert into public.state_capability_dependencies values ('ACQUISITION','PUBLISHER_DISCOVERY','PREREQUISITE',true,'Acquisition requires a verified publisher/access foundation.',true,now(),now()),('STATE_OPERATIONAL_READINESS','PUBLISHER_DISCOVERY','READINESS_EVIDENCE',true,'Operational readiness requires publisher capability evidence.',true,now(),now()),('STATE_OPERATIONAL_READINESS','ACQUISITION','READINESS_EVIDENCE',true,'Operational readiness requires acquisition capability evidence.',true,now(),now()),('STATE_OPERATIONAL_READINESS','BUSINESS_DEVELOPMENT_DISCOVERY','READINESS_EVIDENCE',true,'Operational readiness requires verified business-development access evidence.',true,now(),now()),('STATE_OPERATIONAL_READINESS','OPPORTUNITY_PARTNER_DISCOVERY','READINESS_EVIDENCE',true,'Operational readiness requires opportunity-partner capability evidence.',true,now(),now()),('STATE_OPERATIONAL_READINESS','INSTITUTIONAL_BUYER_DISCOVERY','READINESS_EVIDENCE',true,'Operational readiness requires institutional-buyer capability evidence.',true,now(),now()) on conflict do nothing;
create table public.command_recommendations (id uuid primary key default gen_random_uuid(),state_code text not null references public.state_inventory(state_code) on delete cascade,recommended_mission_type_key text not null references public.command_mission_types(mission_type_key),reason text not null,rationale jsonb not null default '{}'::jsonb,recommendation_status text not null default 'PROPOSED',generated_at timestamptz not null default now(),expires_at timestamptz,superseded_at timestamptz,authorized_run_id uuid references public.command_runs(id) on delete set null,created_at timestamptz not null default now(),check(recommendation_status in ('PROPOSED','AUTHORIZED','DISMISSED','SUPERSEDED','EXPIRED'))); create index command_recommendations_state_status_idx on public.command_recommendations(state_code,recommendation_status,generated_at desc);

create table public.operations_schedules (id uuid primary key default gen_random_uuid(),operation_type text not null,schedule_name text not null,state_codes text[] not null default '{}',frequency_cron text,timezone text not null default 'UTC',enabled boolean not null default false,execution_mode text not null default 'DISABLED',operation_config jsonb not null default '{}'::jsonb,retry_policy jsonb not null default '{}'::jsonb,last_run_at timestamptz,last_result text,next_run_at timestamptz,current_status text not null default 'DISABLED',failure_state jsonb not null default '{}'::jsonb,retry_state jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(execution_mode in ('DISABLED','SHADOW','APPLY')),check(current_status in ('DISABLED','READY','RUNNING','SUCCEEDED','PARTIAL','FAILED','PAUSED'))); create index operations_schedules_next_run_idx on public.operations_schedules(enabled,next_run_at) where enabled=true;
create table public.operations_schedule_runs (id uuid primary key default gen_random_uuid(),schedule_id uuid not null references public.operations_schedules(id) on delete cascade,parent_run_id uuid references public.operations_schedule_runs(id) on delete set null,command_run_id uuid references public.command_runs(id) on delete set null,state_code text,idempotency_key text not null unique,run_status text not null default 'QUEUED',attempt_count integer not null default 0,started_at timestamptz,completed_at timestamptz,result jsonb not null default '{}'::jsonb,warning_count integer not null default 0,failure_count integer not null default 0,evidence jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),check(run_status in ('QUEUED','RUNNING','SUCCEEDED','PARTIAL','FAILED','CANCELLED','RETRY_PENDING'))); create index operations_schedule_runs_schedule_idx on public.operations_schedule_runs(schedule_id,created_at desc); create index operations_schedule_runs_parent_idx on public.operations_schedule_runs(parent_run_id) where parent_run_id is not null;

alter table public.state_contract_opportunities add column if not exists lifecycle_status text,add column if not exists lifecycle_status_at timestamptz,add column if not exists presentation_reason text,add column if not exists presentation_evaluated_at timestamptz,add column if not exists lifecycle_last_processed_at timestamptz,add column if not exists lifecycle_verification_required boolean not null default false,add column if not exists lifecycle_evidence jsonb not null default '{}'::jsonb;
alter table public.state_contract_opportunities add constraint state_contract_lifecycle_status_gate_a_check check(lifecycle_status is null or lifecycle_status in ('OPEN','CLOSING_SOON','CLOSED','AWARD_PENDING','AWARDED','EXPIRED','CANCELLED','ARCHIVED','VERIFICATION_REQUIRED')); create index state_contract_lifecycle_status_idx on public.state_contract_opportunities(state_code,lifecycle_status,response_deadline); create index state_contract_lifecycle_processing_idx on public.state_contract_opportunities(lifecycle_last_processed_at) where lifecycle_last_processed_at is not null; create index state_contract_lifecycle_verification_idx on public.state_contract_opportunities(state_code,response_deadline) where lifecycle_verification_required=true;
create table public.contract_lifecycle_events (id uuid primary key default gen_random_uuid(),opportunity_id uuid not null references public.state_contract_opportunities(id) on delete restrict,evaluation_mode text not null default 'SHADOW',prior_source_status text,proposed_lifecycle_status text,prior_presentation_eligible boolean,proposed_presentation_eligible boolean,decision_reason text not null,evidence jsonb not null default '{}'::jsonb,verification_required boolean not null default false,evaluated_at timestamptz not null default now(),applied_at timestamptz,created_at timestamptz not null default now(),check(evaluation_mode in ('SHADOW','APPLY')),check(proposed_lifecycle_status is null or proposed_lifecycle_status in ('OPEN','CLOSING_SOON','CLOSED','AWARD_PENDING','AWARDED','EXPIRED','CANCELLED','ARCHIVED','VERIFICATION_REQUIRED'))); create index contract_lifecycle_events_opportunity_idx on public.contract_lifecycle_events(opportunity_id,evaluated_at desc); create index contract_lifecycle_events_verification_idx on public.contract_lifecycle_events(verification_required,evaluated_at desc) where verification_required=true;

create or replace function public.command_derive_executive_state(p_status public.command_run_status,p_aadp_state public.aadp_run_state) returns text language sql immutable set search_path=public,pg_temp as $$ select case when p_status='queued' then 'QUEUED' when p_status in ('running','retrying') then 'RUNNING' when p_status in ('stopping','stopped') then 'PAUSED' when p_status='interrupted' then 'ACTION REQUIRED' when p_status='failed' then 'FAILED' when p_status='completed_with_failures' then 'COMPLETED WITH WARNINGS' when p_status='completed' and p_aadp_state='PARTIALLY_COMPLETE' then 'PARTIAL COMPLETE' when p_status='completed' and p_aadp_state='ESCALATED' then 'ACTION REQUIRED' when p_status='completed' then 'COMPLETED' else 'INITIALIZING' end $$;
revoke all on function public.command_derive_executive_state(public.command_run_status,public.aadp_run_state) from public; grant execute on function public.command_derive_executive_state(public.command_run_status,public.aadp_run_state) to authenticated,service_role;
create view public.command_mission_execution_projection with (security_invoker=true) as select r.id mission_id,r.mission_type_key,r.mission_name,r.state_code,r.assigned_agent,r.parent_run_id,r.status canonical_execution_state,r.aadp_state mission_specific_state,public.command_derive_executive_state(r.status,r.aadp_state) executive_display_state,r.current_stage,r.progress_mode,r.progress_value,r.started_at,coalesce(r.last_activity_at,r.updated_at) last_activity_at,r.completed_at,r.result_summary,r.warning_count,r.failure_count,r.action_required,r.execution_evidence,r.registry_impact,r.report_reference from public.command_runs r;
create or replace function public.contract_active_presentation_eligible(p_opportunity_id uuid) returns boolean language sql stable security invoker set search_path=public,pg_temp as $$ select case when o.id is null then false when o.is_latest_version is not true then false when o.duplicate_of is not null then false when lower(o.status) not in ('open','open_continuous') then false when lower(o.status)='open_continuous' then true when o.response_deadline is not null and o.response_deadline<=now() then false when o.lifecycle_status in ('CLOSED','AWARDED','EXPIRED','CANCELLED','ARCHIVED') then false when o.lifecycle_verification_required then false else true end from public.state_contract_opportunities o where o.id=p_opportunity_id $$;
revoke all on function public.contract_active_presentation_eligible(uuid) from public; grant execute on function public.contract_active_presentation_eligible(uuid) to authenticated,service_role;
create view public.contract_presentation_eligibility with (security_invoker=true) as select o.id opportunity_id,o.state_code,o.status source_status,o.lifecycle_status,o.response_deadline,o.last_verified_at,o.last_seen_at,o.last_changed_at,o.is_latest_version,public.contract_active_presentation_eligible(o.id) active_presentation_eligible,case when o.is_latest_version is not true then 'NOT_LATEST_VERSION' when o.duplicate_of is not null then 'DUPLICATE_RECORD' when lower(o.status) not in ('open','open_continuous') then 'SOURCE_STATUS_NOT_OPEN' when o.lifecycle_verification_required then 'VERIFICATION_REQUIRED' when o.lifecycle_status in ('CLOSED','AWARDED','EXPIRED','CANCELLED','ARCHIVED') then 'LIFECYCLE_NOT_ACTIVE' when lower(o.status)='open_continuous' then 'OPEN_CONTINUOUS' when o.response_deadline is not null and o.response_deadline<=now() then 'RESPONSE_DEADLINE_PASSED' else 'ACTIVE_EVIDENCE_SATISFIED' end eligibility_reason from public.state_contract_opportunities o;

create table public.command_notifications (id uuid primary key default gen_random_uuid(),notification_type text not null,severity text not null default 'INFO',state_code text,command_run_id uuid references public.command_runs(id) on delete set null,schedule_run_id uuid references public.operations_schedule_runs(id) on delete set null,opportunity_id uuid references public.state_contract_opportunities(id) on delete set null,title text not null,message text not null,action_required boolean not null default false,navigation_reference text,evidence jsonb not null default '{}'::jsonb,read_at timestamptz,created_at timestamptz not null default now(),check(notification_type in ('MISSION_STARTED','MISSION_MILESTONE','MISSION_COMPLETE','MISSION_COMPLETE_WITH_WARNINGS','MISSION_FAILED','ACTION_REQUIRED','SCHEDULED_OPERATION_COMPLETE','SCHEDULED_OPERATION_FAILED','CONTRACT_LIFECYCLE_EXCEPTION','STATE_READY_FOR_NEXT_MISSION','STATE_ONBOARDING_COMPLETE')),check(severity in ('INFO','WARNING','ERROR','CRITICAL'))); create index command_notifications_action_idx on public.command_notifications(action_required,created_at desc); create index command_notifications_run_idx on public.command_notifications(command_run_id,created_at desc) where command_run_id is not null;
create table public.command_audit_log (id bigint generated always as identity primary key,entity_type text not null,entity_id text not null,action_type text not null,actor_type text not null,actor_id text,command_run_id uuid references public.command_runs(id) on delete set null,previous_state jsonb not null default '{}'::jsonb,new_state jsonb not null default '{}'::jsonb,reason text not null,evidence jsonb not null default '{}'::jsonb,occurred_at timestamptz not null default now(),check(actor_type in ('SYSTEM','OPERATOR','SCHEDULER','LIFECYCLE_PROCESSOR','AGENT','MIGRATION'))); create index command_audit_log_entity_idx on public.command_audit_log(entity_type,entity_id,occurred_at desc); create index command_audit_log_run_idx on public.command_audit_log(command_run_id,occurred_at desc) where command_run_id is not null;

alter table public.command_mission_types enable row level security; alter table public.command_stage_projection enable row level security; alter table public.state_inventory enable row level security; alter table public.state_capability_status enable row level security; alter table public.state_capability_dependencies enable row level security; alter table public.command_recommendations enable row level security; alter table public.operations_schedules enable row level security; alter table public.operations_schedule_runs enable row level security; alter table public.contract_lifecycle_events enable row level security; alter table public.command_notifications enable row level security; alter table public.command_audit_log enable row level security;
grant select on public.command_mission_types,public.command_stage_projection,public.state_inventory,public.state_capability_status,public.state_capability_dependencies,public.command_recommendations,public.operations_schedules,public.operations_schedule_runs,public.contract_lifecycle_events,public.command_notifications,public.command_audit_log to authenticated; grant all on public.command_mission_types,public.command_stage_projection,public.state_inventory,public.state_capability_status,public.state_capability_dependencies,public.command_recommendations,public.operations_schedules,public.operations_schedule_runs,public.contract_lifecycle_events,public.command_notifications,public.command_audit_log to service_role; grant usage,select on sequence public.command_audit_log_id_seq to service_role; revoke all on public.command_mission_types,public.command_stage_projection,public.state_inventory,public.state_capability_status,public.state_capability_dependencies,public.command_recommendations,public.operations_schedules,public.operations_schedule_runs,public.contract_lifecycle_events,public.command_notifications,public.command_audit_log from anon;
