grant select on public.command_mission_execution_projection,public.contract_presentation_eligibility to authenticated,service_role; revoke all on public.command_mission_execution_projection,public.contract_presentation_eligibility from anon;

-- Architectural controls: active presentation and executive operational state are derived, not independently writable.